                        CheckBox {
                            text: qsTr("Black sil.")
                            font.pixelSize: 10
                            checked: mlBridge.blackSilhouette
                            onToggled: mlBridge.blackSilhouette = checked
                        }
                        Label {
                            text: qsTr("Implant:")
                            color: Theme.fgMuted
                            font.pixelSize: 10
                        }
                        ButtonGroup {
                            id: implantGroup
                            buttons: [femurKindButton, tibiaKindButton]
                        }
                        Button {
                            id: femurKindButton
                            text: qsTr("Fem")
                            checkable: true
                            checked: mlBridge.implantKind === 0
                            font.pixelSize: 10
                            implicitWidth: 40
                            onClicked: mlBridge.implantKind = 0
                        }
                        Button {
                            id: tibiaKindButton
                            text: qsTr("Tib")
                            checkable: true
                            checked: mlBridge.implantKind === 1
                            font.pixelSize: 10
                            implicitWidth: 40
                            onClicked: mlBridge.implantKind = 1
                        }
                    }
                    RowLayout {
                        Layout.fillWidth: true
                        spacing: 4
                        Label {
                            text: qsTr("View:")
                            color: Theme.fgMuted
                            font.pixelSize: 10
                        }
                        ButtonGroup {
                            id: viewGroup
                            buttons: [origViewButton, segViewButton]
                        }
