                        // mid-run settings/pose edit cannot race the run.
                        settingsDialog.close()
                        poseDialog.close()
                        optimizerBridge.run()
                    }
                }
                Button {
                    text: qsTr("Stop")
                    enabled: optimizerBridge.running
                    onClicked: optimizerBridge.stop()
                }
                ProgressBar {
                    id: progress
                    Layout.fillWidth: true
                    from: 0
                    to: 100
                    value: optimizerBridge.progress * 100
