                    text: qsTr("calls %1").arg(optimizerBridge.costCalls)
                    color: Theme.fgDim
                    font.pixelSize: 11
                }
                Label {
                    text: qsTr("min %1")
                              .arg(optimizerBridge.currentMinimum.toFixed(3))
                    color: Theme.fgDim
                    font.pixelSize: 11
                }
            }
        }
    }
}

